    {
        p.setValue(ObjectBridge::getInstance(L, index));
        return;
    }

    if (p.getDescriptor().type == Type::singleton<boost::shared_ptr<DescribedBase> >())
    {
        p.setValue(ObjectBridge::getPtr(L, index));
        return;
